    titleEn: "History: The Classical World - Board Revision Notes",
    titleTa: "\u0bb5\u0bb0\u0bb2\u0bbe\u0bb1\u0bc1: \u0b9a\u0bc6\u0bb5\u0bcd\u0bb5\u0bbf\u0baf\u0bb2\u0bcd \u0b89\u0bb2\u0b95\u0bae\u0bcd - \u0ba4\u0bc7\u0bb0\u0bcd\u0bb5\u0bc1 \u0bb5\u0bb4\u0bbf\u0b95\u0bbe\u0b9f\u0bcd\u0b9f\u0bbf\u0b95\u0bcd \u0b95\u0bc1\u0bb1\u0bbf\u0baa\u0bcd\u0baa\u0bc1\u0b95\u0bb3\u0bcd",
    publishedAt: '21 Sep 2026',
    publishedAtTa: '21 செப் 2026',
